{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31", "C38"],
      "claim": "Transferred absolute oral bioavailability measurements in healthy humans are consistently at or above 20%, e.g. verapamil 34% and noscapine 30%."
    },
    {
      "card_ids": ["C18", "C08"],
      "claim": "Additional transferred molecules exceed the 20% threshold under ordinary conditions, e.g. sulpiride 30% and encainide 32±7%."
    },
    {
      "card_ids": ["C22", "C65"],
      "claim": "Low values are mostly qualitative or from altered conditions such as rifampin coadministration, and do not outweigh the consistent ordinary-condition high F evidence."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C17", "C71", "C29", "C65", "C13"],
  "decision_summary": "All ten transferred evidence molecules have ordinary-condition absolute oral bioavailability values at or above the 20% threshold (mostly 23–90%), with only borderline or altered-condition low values; therefore predict high.",
  "evidence_gaps": [
    "Some records report ranges that dip below 20% (e.g. verapamil 18–20%, noscapine 16–58%, encainide 7–82%, codeine 15–80%), leaving threshold-adjacent uncertainty.",
    "Several low values come from disease states or drug interactions (cirrhosis, rifampin) and are less transferable to ordinary conditions."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C31", "C38", "C18", "C08", "C16"],
  "revision_action": "initial",
  "supportive_card_ids": ["C31", "C38", "C18", "C08", "C16", "C60", "C37", "C26"]
}

